 95 | 	// Decrease a user's share for the pool and have any pending rewards sent to them.
 96 | 	// Does not require the pool to be valid (in case the pool was recently unwhitelisted).
 97 | 	function _decreaseUserShare( address wallet, bytes32 poolID, uint256 decreaseShareAmount, bool useCooldown ) internal
 98 | 		{
 99 | 		require( decreaseShareAmount != 0, "Cannot decrease zero share" );
100 | 
101 | 		UserShareInfo storage user = _userShareInfo[wallet][poolID];
102 | 		require( decreaseShareAmount <= user.userShare, "Cannot decrease more than existing user share" );
103 | 
104 | 		if ( useCooldown )
105 | 		if ( msg.sender != address(exchangeConfig.dao()) ) // DAO doesn't use the cooldown
106 | 			{
107 | 			require( block.timestamp >= user.cooldownExpiration, "Must wait for the cooldown to expire" );
108 | 
109 | 			// Update the cooldown expiration for future transactions
110 | 			user.cooldownExpiration = block.timestamp + stakingConfig.modificationCooldown();
111 | 			}
112 | 
113 | 		// Determine the share of the rewards for the amountToDecrease (will include previously added virtual rewards)
114 | 		uint256 rewardsForAmount = ( totalRewards[poolID] * decreaseShareAmount ) / totalShares[poolID];
